    private static readonly FrozenDictionary<string, PublicOperationPolicy> ById =
        All.ToFrozenDictionary(operation => operation.OperationId, StringComparer.Ordinal);

    /// <summary>Finds an exact case-sensitive operation ID. Unknown IDs return false; nothing is inferred or registered.</summary>
    public static bool TryGet(string operationId, [NotNullWhen(true)] out PublicOperationPolicy? policy)
    {
        ArgumentNullException.ThrowIfNull(operationId);
        return ById.TryGetValue(operationId, out policy);
    }
